<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Dune Line — Overnight Desert Express</title>
<style>
  *,*::before,*::after{margin:0;padding:0;box-sizing:border-box}
  :root{
    --bg-deep:#08080d;--bg-primary:#0c0c14;--bg-card:#13131f;--bg-card-hover:#1a1a2a;
    --border:#22223a;--border-light:#2a2a44;
    --text-primary:#efe9e1;--text-secondary:#9a94a8;--text-muted:#6a6480;
    --amber:#f0a830;--amber-dim:#c48420;--amber-glow:rgba(240,168,48,.15);
    --cyan:#00e5ff;--cyan-dim:#0099aa;--cyan-glow:rgba(0,229,255,.12);
    --magenta:#ff3caa;--magenta-glow:rgba(255,60,170,.12);
    --sand:#d4b896;
    --radius:12px;--radius-lg:20px;
    --font-display:Georgia,'Times New Roman',serif;
    --font-body:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;
  }
  html{scroll-behavior:smooth;font-size:16px}
  body{font-family:var(--font-body);background:var(--bg-deep);color:var(--text-primary);line-height:1.6;overflow-x:hidden;-webkit-font-smoothing:antialiased}

  /* ── NAV ── */
  nav{position:fixed;top:0;left:0;right:0;z-index:100;display:flex;align-items:center;justify-content:space-between;padding:0 clamp(1.5rem,4vw,4rem);height:72px;background:rgba(8,8,13,.75);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-bottom:1px solid rgba(255,255,255,.04);transition:background .3s}
  .nav-logo{display:flex;align-items:center;gap:.6rem;text-decoration:none;color:var(--text-primary)}
  .nav-logo svg{width:32px;height:32px}
  .nav-logo span{font-family:var(--font-display);font-size:1.25rem;font-weight:700;letter-spacing:.02em}
  .nav-logo .accent{color:var(--amber)}
  .nav-links{display:flex;align-items:center;gap:2rem;list-style:none}
  .nav-links a{text-decoration:none;color:var(--text-secondary);font-size:.875rem;font-weight:500;letter-spacing:.03em;text-transform:uppercase;transition:color .25s;position:relative}
  .nav-links a::after{content:'';position:absolute;bottom:-4px;left:0;width:0;height:1.5px;background:var(--amber);transition:width .3s}
  .nav-links a:hover{color:var(--text-primary)}
  .nav-links a:hover::after{width:100%}
  .nav-cta{padding:.55rem 1.4rem;background:transparent;border:1px solid var(--amber);color:var(--amber);border-radius:100px;font-size:.8rem;font-weight:600;text-transform:uppercase;letter-spacing:.08em;text-decoration:none;transition:all .3s}
  .nav-cta:hover{background:var(--amber);color:var(--bg-deep)}
  .nav-toggle{display:none;flex-direction:column;gap:5px;background:none;border:none;cursor:pointer;padding:4px}
  .nav-toggle span{display:block;width:22px;height:2px;background:var(--text-primary);border-radius:2px;transition:all .3s}

  /* ── HERO ── */
  .hero{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;position:relative;padding:6rem clamp(1.5rem,4vw,4rem) 4rem;overflow:hidden;text-align:center}
  .hero-bg{position:absolute;inset:0;z-index:0}
  /* Desert horizon */
  .hero-bg::before{content:'';position:absolute;bottom:0;left:0;right:0;height:40%;background:linear-gradient(to top,rgba(180,120,40,.08) 0%,transparent 100%)}
  /* Stars */
  .hero-bg .stars{position:absolute;inset:0}
  .star{position:absolute;border-radius:50%;background:#fff;animation:twinkle var(--d,3s) ease-in-out infinite alternate}
  @keyframes twinkle{0%{opacity:.2;transform:scale(.8)}100%{opacity:1;transform:scale(1.2)}}
  /* Neon city glow */
  .hero-bg .city-glow{position:absolute;bottom:18%;right:5%;width:300px;height:180px;border-radius:50%;background:radial-gradient(ellipse,rgba(0,229,255,.08) 0%,rgba(255,60,170,.04) 40%,transparent 70%);filter:blur(40px);animation:cityPulse 6s ease-in-out infinite alternate}
  @keyframes cityPulse{0%{opacity:.6;transform:scale(1)}100%{opacity:1;transform:scale(1.1)}}
  /* Desert dunes SVG */
  .hero-dunes{position:absolute;bottom:0;left:0;right:0;z-index:1}
  .hero-content{position:relative;z-index:2;max-width:900px}
  .hero-badge{display:inline-flex;align-items:center;gap:.5rem;padding:.45rem 1.2rem;border-radius:100px;background:var(--amber-glow);border:1px solid rgba(240,168,48,.2);color:var(--amber);font-size:.75rem;font-weight:600;text-transform:uppercase;letter-spacing:.12em;margin-bottom:2rem}
  .hero-badge .dot{width:6px;height:6px;border-radius:50%;background:var(--amber);animation:pulse 2s ease-in-out infinite}
  @keyframes pulse{0%,100%{opacity:1}50%{opacity:.3}}
  .hero h1{font-family:var(--font-display);font-size:clamp(3rem,7vw,6.5rem);font-weight:700;line-height:1.05;letter-spacing:-.03em;margin-bottom:1.5rem}
  .hero h1 .line1{display:block;color:var(--text-primary)}
  .hero h1 .line2{display:block;background:linear-gradient(135deg,var(--amber) 0%,var(--cyan) 50%,var(--magenta) 100%);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
  .hero-sub{font-size:clamp(1rem,1.8vw,1.3rem);color:var(--text-secondary);max-width:580px;margin:0 auto 2.5rem;line-height:1.7;font-weight:300}
  .hero-actions{display:flex;gap:1rem;justify-content:center;flex-wrap:wrap}
  .btn-primary{display:inline-flex;align-items:center;gap:.5rem;padding:.9rem 2.2rem;background:linear-gradient(135deg,var(--amber),var(--amber-dim));color:var(--bg-deep);border:none;border-radius:100px;font-size:.95rem;font-weight:700;text-decoration:none;letter-spacing:.02em;transition:all .3s;box-shadow:0 4px 30px rgba(240,168,48,.25)}
  .btn-primary:hover{transform:translateY(-2px);box-shadow:0 8px 40px rgba(240,168,48,.35)}
  .btn-secondary{display:inline-flex;align-items:center;gap:.5rem;padding:.9rem 2.2rem;background:transparent;color:var(--text-primary);border:1px solid var(--border-light);border-radius:100px;font-size:.95rem;font-weight:500;text-decoration:none;transition:all .3s}
  .btn-secondary:hover{border-color:var(--text-secondary);background:rgba(255,255,255,.03)}
  /* Train illustration */
  .hero-train{position:absolute;bottom:12%;left:5%;z-index:2;opacity:.12;animation:trainMove 30s linear infinite}
  @keyframes trainMove{0%{transform:translateX(-100px)}100%{transform:translateX(calc(100vw + 100px))}}
  /* Stats bar */
  .hero-stats{display:flex;justify-content:center;gap:clamp(2rem,5vw,4rem);margin-top:4rem;padding-top:3rem;border-top:1px solid var(--border);width:100%;max-width:700px}
  .hero-stat{text-align:center}
  .hero-stat .num{font-family:var(--font-display);font-size:2rem;font-weight:700;color:var(--text-primary)}
  .hero-stat .num .unit{font-size:.8em;color:var(--amber)}
  .hero-stat .label{font-size:.75rem;color:var(--text-muted);text-transform:uppercase;letter-spacing:.1em;margin-top:.25rem}

  /* ── SECTION COMMON ── */
  section{padding:clamp(4rem,8vw,8rem) clamp(1.5rem,4vw,4rem)}
  .section-label{display:inline-flex;align-items:center;gap:.5rem;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.18em;color:var(--cyan);margin-bottom:1rem}
  .section-label::before{content:'';width:20px;height:1px;background:var(--cyan)}
  .section-title{font-family:var(--font-display);font-size:clamp(2rem,4vw,3.2rem);font-weight:700;line-height:1.15;letter-spacing:-.02em;margin-bottom:1rem}
  .section-desc{color:var(--text-secondary);font-size:1.05rem;max-width:560px;line-height:1.7;font-weight:300}
  .section-header{text-align:center;margin-bottom:clamp(3rem,5vw,5rem)}
  .section-header .section-desc{margin:0 auto}

  /* ── FEATURES ── */
  .features{background:var(--bg-primary);position:relative}
  .features::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--border-light),transparent)}
  .features-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:2rem;max-width:1200px;margin:0 auto}
  .feature-card{position:relative;padding:2.5rem;border-radius:var(--radius-lg);background:var(--bg-card);border:1px solid var(--border);transition:all .4s;overflow:hidden}
  .feature-card:hover{border-color:var(--border-light);transform:translateY(-4px);background:var(--bg-card-hover)}
  .feature-card::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--amber),var(--cyan));opacity:0;transition:opacity .4s}
  .feature-card:hover::before{opacity:1}
  .feature-icon{width:56px;height:56px;border-radius:14px;display:flex;align-items:center;justify-content:center;margin-bottom:1.5rem;position:relative}
  .feature-icon.amber{background:var(--amber-glow);color:var(--amber)}
  .feature-icon.cyan{background:var(--cyan-glow);color:var(--cyan)}
  .feature-icon.magenta{background:var(--magenta-glow);color:var(--magenta)}
  .feature-card h3{font-family:var(--font-display);font-size:1.35rem;font-weight:700;margin-bottom:.75rem;letter-spacing:-.01em}
  .feature-card p{color:var(--text-secondary);font-size:.925rem;line-height:1.7;font-weight:300}

  /* ── TIMETABLE ── */
  .timetable{position:relative}
  .timetable::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--border-light),transparent)}
  .timetable-wrapper{max-width:900px;margin:0 auto}
  .timetable-list{display:flex;flex-direction:column;gap:1px;background:var(--border);border-radius:var(--radius-lg);overflow:hidden;border:1px solid var(--border)}
  .tt-header{display:grid;grid-template-columns:1fr 1fr 1fr 1fr auto;background:var(--bg-card)}
  .tt-row{display:grid;grid-template-columns:1fr 1fr 1fr 1fr auto;background:var(--bg-card);transition:background .3s}
  .tt-row:hover{background:var(--bg-card-hover)}
  .tt-cell{padding:1.5rem 1.75rem;font-size:.9rem}
  .tt-header .tt-cell{font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.12em;color:var(--text-muted);background:var(--bg-card)}
  .tt-cell.time{font-family:var(--font-display);font-size:1.15rem;font-weight:700;color:var(--text-primary)}
  .tt-cell.time .period{font-size:.75rem;font-weight:400;color:var(--text-muted);margin-left:.25rem}
  .tt-cell.dest{color:var(--text-secondary);font-weight:500}
  .tt-cell.duration{color:var(--text-muted);font-size:.85rem}
  .tt-cell.duration svg{vertical-align:middle;margin-right:.3rem}
  .tt-badge{display:inline-block;padding:.25rem .75rem;border-radius:100px;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em}
  .tt-badge.available{background:rgba(0,229,255,.1);color:var(--cyan);border:1px solid rgba(0,229,255,.2)}
  .tt-badge.limited{background:rgba(240,168,48,.1);color:var(--amber);border:1px solid rgba(240,168,48,.2)}
  .tt-badge.waitlist{background:rgba(255,60,170,.08);color:var(--magenta);border:1px solid rgba(255,60,170,.15)}
  .tt-book{padding:.5rem 1.2rem;border-radius:100px;font-size:.75rem;font-weight:600;text-transform:uppercase;letter-spacing:.06em;text-decoration:none;border:1px solid var(--border-light);color:var(--text-secondary);background:transparent;cursor:pointer;transition:all .3s;white-space:nowrap}
  .tt-book:hover{border-color:var(--amber);color:var(--amber);background:var(--amber-glow)}

  /* ── PRICING ── */
  .pricing{background:var(--bg-primary);position:relative}
  .pricing::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--border-light),transparent)}
  .pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1.5rem;max-width:1100px;margin:0 auto;align-items:start}
  .price-card{position:relative;padding:2.5rem 2rem;border-radius:var(--radius-lg);background:var(--bg-card);border:1px solid var(--border);transition:all .4s}
  .price-card:hover{transform:translateY(-4px)}
  .price-card.featured{border-color:var(--amber);background:linear-gradient(180deg,rgba(240,168,48,.04) 0%,var(--bg-card) 40%);padding-top:2.5rem}
  .price-card.featured::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--amber),var(--cyan))}
  .price-popular{position:absolute;top:-12px;left:50%;transform:translateX(-50%);padding:.3rem 1rem;background:linear-gradient(135deg,var(--amber),var(--amber-dim));color:var(--bg-deep);font-size:.65rem;font-weight:800;text-transform:uppercase;letter-spacing:.12em;border-radius:100px;white-space:nowrap}
  .price-tier{font-size:.75rem;font-weight:700;text-transform:uppercase;letter-spacing:.15em;color:var(--text-muted);margin-bottom:.5rem}
  .price-amount{font-family:var(--font-display);font-size:3rem;font-weight:700;line-height:1;margin-bottom:.25rem}
  .price-amount .currency{font-size:1.2rem;vertical-align:super;color:var(--text-secondary);font-weight:400}
  .price-per{font-size:.8rem;color:var(--text-muted);margin-bottom:2rem}
  .price-features{list-style:none;display:flex;flex-direction:column;gap:.85rem;margin-bottom:2rem}
  .price-features li{display:flex;align-items:flex-start;gap:.65rem;font-size:.875rem;color:var(--text-secondary);line-height:1.5}
  .price-features li svg{flex-shrink:0;margin-top:2px;color:var(--amber)}
  .price-btn{display:block;width:100%;padding:.85rem;border-radius:100px;font-size:.85rem;font-weight:700;text-align:center;text-decoration:none;letter-spacing:.04em;text-transform:uppercase;transition:all .3s;cursor:pointer}
  .price-btn.outline{background:transparent;border:1px solid var(--border-light);color:var(--text-secondary)}
  .price-btn.outline:hover{border-color:var(--text-primary);color:var(--text-primary)}
  .price-btn.filled{background:linear-gradient(135deg,var(--amber),var(--amber-dim));border:none;color:var(--bg-deep);box-shadow:0 4px 25px rgba(240,168,48,.2)}
  .price-btn.filled:hover{box-shadow:0 8px 35px rgba(240,168,48,.3);transform:translateY(-1px)}

  /* ── TESTIMONIAL ── */
  .testimonial{position:relative}
  .testimonial::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--border-light),transparent)}
  .testimonial-inner{max-width:800px;margin:0 auto;text-align:center;position:relative}
  .testimonial-quote{font-family:var(--font-display);font-size:clamp(1.3rem,2.5vw,1.85rem);font-weight:400;line-height:1.65;color:var(--text-primary);font-style:italic;position:relative;padding:0 2rem}
  .testimonial-quote::before{content:'\201C';position:absolute;left:-.5rem;top:-.5rem;font-size:4rem;color:var(--amber);opacity:.3;line-height:1;font-style:normal}
  .testimonial-author{display:flex;flex-direction:column;align-items:center;gap:.5rem;margin-top:2.5rem}
  .testimonial-avatar{width:52px;height:52px;border-radius:50%;background:linear-gradient(135deg,var(--amber),var(--magenta));display:flex;align-items:center;justify-content:center;font-family:var(--font-display);font-size:1.2rem;font-weight:700;color:var(--bg-deep)}
  .testimonial-name{font-weight:600;font-size:.95rem}
  .testimonial-role{font-size:.8rem;color:var(--text-muted)}
  .testimonial-stars{display:flex;gap:4px;justify-content:center;margin-top:.75rem}
  .testimonial-stars svg{color:var(--amber)}

  /* ── FOOTER ── */
  footer{padding:clamp(3rem,5vw,5rem) clamp(1.5rem,4vw,4rem) 2rem;border-top:1px solid var(--border);background:var(--bg-primary)}
  .footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:3rem;max-width:1200px;margin:0 auto 3rem}
  .footer-brand p{color:var(--text-muted);font-size:.85rem;line-height:1.7;margin-top:1rem;max-width:280px}
  .footer-col h4{font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.15em;color:var(--text-muted);margin-bottom:1.25rem}
  .footer-col ul{list-style:none;display:flex;flex-direction:column;gap:.65rem}
  .footer-col a{color:var(--text-secondary);text-decoration:none;font-size:.875rem;transition:color .25s}
  .footer-col a:hover{color:var(--amber)}
  .footer-bottom{display:flex;justify-content:space-between;align-items:center;padding-top:2rem;border-top:1px solid var(--border);max-width:1200px;margin:0 auto}
  .footer-bottom p{font-size:.75rem;color:var(--text-muted)}
  .footer-socials{display:flex;gap:1rem}
  .footer-socials a{width:36px;height:36px;border-radius:50%;border:1px solid var(--border);display:flex;align-items:center;justify-content:center;color:var(--text-muted);text-decoration:none;transition:all .3s;font-size:.8rem}
  .footer-socials a:hover{border-color:var(--amber);color:var(--amber);background:var(--amber-glow)}

  /* ── ANIMATIONS ── */
  .fade-up{opacity:0;transform:translateY(30px);transition:all .7s cubic-bezier(.16,1,.3,1)}
  .fade-up.visible{opacity:1;transform:translateY(0)}
  .fade-up.d1{transition-delay:.1s}.fade-up.d2{transition-delay:.2s}.fade-up.d3{transition-delay:.3s}.fade-up.d4{transition-delay:.4s}

  /* ── RESPONSIVE ── */
  @media(max-width:1024px){
    .features-grid,.pricing-grid{grid-template-columns:1fr 1fr}
    .footer-grid{grid-template-columns:1fr 1fr}
  }
  @media(max-width:768px){
    .nav-links{display:none;position:fixed;top:72px;left:0;right:0;background:rgba(8,8,13,.95);backdrop-filter:blur(20px);flex-direction:column;padding:2rem;gap:1.5rem;border-bottom:1px solid var(--border)}
    .nav-links.open{display:flex}
    .nav-toggle{display:flex}
    .features-grid,.pricing-grid{grid-template-columns:1fr}
    .tt-header,.tt-row{grid-template-columns:1fr 1fr}
    .tt-cell.hide-mobile{display:none}
    .hero-stats{flex-direction:column;gap:1.5rem}
    .footer-grid{grid-template-columns:1fr;gap:2rem}
    .footer-bottom{flex-direction:column;gap:1rem;text-align:center}
    .hero-train{display:none}
  }
  @media(max-width:480px){
    .tt-header,.tt-row{grid-template-columns:1fr}
    .tt-cell.hide-phone{display:none}
  }
</style>
</head>
<body>

<!-- ════════ NAV ════════ -->
<nav>
  <a href="#" class="nav-logo">
    <svg viewBox="0 0 32 32" fill="none" xmlns="http://www.w3.org/2000/svg">
      <circle cx="16" cy="16" r="14" stroke="currentColor" stroke-width="1.5" opacity=".3"/>
      <path d="M8 20L16 8L24 20" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
      <line x1="11" y1="17" x2="21" y2="17" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" opacity=".5"/>
    </svg>
    <span>Dune <span class="accent">Line</span></span>
  </a>
  <ul class="nav-links" id="navLinks">
    <li><a href="#features">Features</a></li>
    <li><a href="#timetable">Schedule</a></li>
    <li><a href="#pricing">Fares</a></li>
    <li><a href="#testimonial">Reviews</a></li>
    <li><a href="#pricing" class="nav-cta">Book Now</a></li>
  </ul>
  <button class="nav-toggle" id="navToggle" aria-label="Menu">
    <span></span><span></span><span></span>
  </button>
</nav>

<!-- ════════ HERO ════════ -->
<section class="hero">
  <div class="hero-bg">
    <div class="stars" id="stars"></div>
    <div class="city-glow"></div>
  </div>

  <!-- Dunes SVG -->
  <svg class="hero-dunes" viewBox="0 0 1440 320" preserveAspectRatio="none" style="height:220px;width:100%">
    <defs>
      <linearGradient id="dune1" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="rgba(180,120,40,.06)"/>
        <stop offset="100%" stop-color="rgba(180,120,40,.02)"/>
      </linearGradient>
      <linearGradient id="dune2" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="rgba(140,90,30,.08)"/>
        <stop offset="100%" stop-color="rgba(140,90,30,.03)"/>
      </linearGradient>
    </defs>
    <path d="M0,240 Q180,140 360,200 Q540,260 720,180 Q900,100 1080,170 Q1260,240 1440,190 L1440,320 L0,320Z" fill="url(#dune1)"/>
    <path d="M0,260 Q200,200 400,240 Q600,280 800,220 Q1000,160 1200,220 Q1350,260 1440,230 L1440,320 L0,320Z" fill="url(#dune2)"/>
    <!-- Track line -->
    <line x1="0" y1="295" x2="1440" y2="295" stroke="rgba(255,255,255,.06)" stroke-width="1"/>
    <line x1="0" y1="299" x2="1440" y2="299" stroke="rgba(255,255,255,.04)" stroke-width="1"/>
  </svg>

  <!-- Animated train SVG -->
  <svg class="hero-train" width="180" height="50" viewBox="0 0 180 50" fill="none">
    <rect x="10" y="10" width="120" height="28" rx="6" stroke="currentColor" stroke-width="1.5" fill="none"/>
    <rect x="140" y="6" width="34" height="32" rx="4" stroke="currentColor" stroke-width="1.5" fill="none"/>
    <circle cx="25" cy="42" r="5" stroke="currentColor" stroke-width="1.5"/>
    <circle cx="55" cy="42" r="5" stroke="currentColor" stroke-width="1.5"/>
    <circle cx="85" cy="42" r="5" stroke="currentColor" stroke-width="1.5"/>
    <circle cx="115" cy="42" r="5" stroke="currentColor" stroke-width="1.5"/>
    <circle cx="152" cy="42" r="5" stroke="currentColor" stroke-width="1.5"/>
