<script>
// Stars generation
(function(){
  const c=document.getElementById('stars');
  if(!c)return;
  for(let i=0;i<80;i++){
    const s=document.createElement('div');
    s.className='star';
    const size=Math.random()*2+1;
    s.style.cssText=`width:${size}px;height:${size}px;top:${Math.random()*60}%;left:${Math.random()*100}%;--d:${Math.random()*4+2}s;animation-delay:${Math.random()*3}s;opacity:${Math.random()*.6+.2}`;
    c.appendChild(s);
  }
})();

// Mobile nav toggle
const toggle=document.getElementById('navToggle');
const links=document.getElementById('navLinks');
if(toggle&&links){
  toggle.addEventListener('click',()=>{
    links.classList.toggle('open');
    const spans=toggle.querySelectorAll('span');
    if(links.classList.contains('open')){
      spans[0].style.transform='rotate(45deg) translate(5px,5px)';
      spans[1].style.opacity='0';
      spans[2].style.transform='rotate(-45deg) translate(5px,-5px)';
    }else{
      spans[0].style.transform='';
      spans[1].style.opacity='';
      spans[2].style.transform='';
    }
  });
  links.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{
    links.classList.remove('open');
    const spans=toggle.querySelectorAll('span');
    spans[0].style.transform='';spans[1].style.opacity='';spans[2].style.transform='';
  }));
}

// Scroll reveal
const observer=new IntersectionObserver((entries)=>{
  entries.forEach(e=>{
    if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}
  });
},{threshold:0.1,rootMargin:'0px 0px -40px 0px'});
document.querySelectorAll('.fade-up').forEach(el=>observer.observe(el));

// Nav background on scroll
const nav=document.querySelector('nav');
window.addEventListener('scroll',()=>{
  if(window.scrollY>50){
    nav.style.background='rgba(8,8,13,.92)';
  }else{
    nav.style.background='rgba(8,8,13,.75)';
  }
},{passive:true});
</script>
